(()=>{const RULES={work:{slugs:['ai-literacy-for-the-modern-workplace','the-artificial-intelligence-job-shift-navigating-the-future-of-work','ai-agents-for-everyday-work'],reason:'Work, skills and role change are the strongest match.'},agents:{slugs:['ai-agents-for-everyday-work','ai-literacy-for-the-modern-workplace','artificial-intelligence-for-small-business'],reason:'Starts with practical agent use, then adds literacy and adoption context.'},business:{slugs:['artificial-intelligence-for-small-business','artificial-intelligence-powered-retail-revolutionizing-customer-experience-for-a-sustainable-future','artificial-intelligence-in-industry-a-comprehensive-guide'],reason:'Prioritises practical adoption, customers and operational decisions.'},healthcare:{slugs:['digital-diagnosis-how-ai-is-revolutionizing-healthcare','artificial-intelligence-in-pharmaceuticals-revolutionizing-healthcare','artificial-intelligence-in-veterinary-medicine-transforming-animal-healthcare-through-innovation'],reason:'Focuses on clinical and care use before adjacent healthcare sectors.'},regulated:{slugs:['artificial-intelligence-and-the-law-case-studies-and-future-trends','artificial-intelligence-in-banking-revolutionizing-finance-and-data-security','digital-diagnosis-how-ai-is-revolutionizing-healthcare'],reason:'Covers law, finance and healthcare where accountability matters most.'},trust:{slugs:['deepfakes-ai-scams-and-synthetic-reality','artificial-intelligence-for-cyber-security-a-practical-guide-to-data-breach-prevention','the-dumbening-how-ai-is-reshaping-our-minds'],reason:'Starts with synthetic-media verification, then security and human judgement.'},fundamentals:{slugs:['the-artificial-intelligence-revolution-from-algorithms-to-consciousness','the-architects-of-ai-pioneers-breakthroughs-and-the-road-ahead','ai-literacy-for-the-modern-workplace'],reason:'Builds from core concepts and history into practical literacy.'}};let books=null;async function load(){if(books)return books;const r=await fetch('/api/v1/books.json',{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('catalogue unavailable');books=await r.json();return books}function esc(v){return String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function submit(e){e.preventDefault();const form=e.currentTarget,goal=form.goal.value,out=document.getElementById('book-finder-results');if(!RULES[goal])return;const source=new URLSearchParams(location.search).get('source')||'book_finder';window.JHAnalytics?.track('book_finder_start',{placement:source});out.innerHTML='<h2>Your starting books</h2><p>Checking the governed catalogue…</p>';try{const data=await load(),by=new Map(data.map(b=>[b.slug,b])),rule=RULES[goal],found=rule.slugs.map(s=>by.get(s)).filter(Boolean).slice(0,3);out.innerHTML='<h2>Your starting books</h2><p>'+esc(rule.reason)+'</p><div class="grid">'+found.map((b,i)=>'<article class="card"><p class="eyebrow">Pick '+(i+1)+'</p><h3>'+esc(b.title)+'</h3><p>'+esc(b.short||b.summary||'')+'</p><div class="actions"><a class="button secondary" href="/ebooks/'+esc(b.slug)+'/" data-book-slug="'+esc(b.slug)+'" data-placement="book_finder">View book</a><a class="button" href="'+esc(b.buy_route)+'" data-ebook-amazon data-book-slug="'+esc(b.slug)+'" data-placement="book_finder">Buy on Amazon</a></div></article>').join('')+'</div>';window.JHAnalytics?.track('book_finder_complete',{placement:source,topic:goal})}catch{out.innerHTML='<h2>Your starting books</h2><p>The live catalogue could not be loaded. Use the <a href="/bundles/">reading paths</a> or <a href="/ebooks/">full catalogue</a>.</p>'}}function wire(){document.getElementById('book-finder-form')?.addEventListener('submit',submit)}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',wire,{once:true}):wire()})();
